    BOOL bSuccess = FALSE;
    DWORD dwPeekResult;
    CHAR* buffer = NULL;
    DWORD dwBufferSize = 0;

    // Check if data is available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwAvail, NULL)) {
        SetLastError(ERROR_EMPTY);
        return FALSE;
    }

    if (dwAvail == 0) {
        SetLastError(ERROR_EMPTY);
        return FALSE;
    }

    // Allocate memory to read the data
    buffer = (CHAR*)HeapAlloc(GPTR, dwAvail);
    if (!buffer) {
        SetLastError(ERROR_NOT_ENOUGH_MEMORY);
