    CHAR* token = strtok(buffer, "\0");
    if (!token || strlen(token) == 0) {
        // No working directory provided
        sud->workingDirectory[0] = '\0';
    } else {
        strncpy_s(sud->workingDirectory, MAX_PATH, token, _TRUNCATE);
