BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD bytesAvailable = 0;
    DWORD bytesRead = 0;
    BOOL result = FALSE;
    char* buffer = NULL;

    // Check if data is available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &bytesAvailable, NULL)) {
        LogError("Failed to peek named pipe for data availability.");
        return FALSE;
    }

    if (bytesAvailable == 0) {
        return FALSE;
    }

    buffer = (char*)HeapAlloc(GPTR, bytesAvailable + 1); // +1 for NULL-termination
    if (!buffer) {
        LogError("Memory allocation failed for reading data from pipe.");
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, bytesAvailable, &bytesRead, NULL)) {
        LogError("Failed to read data from the named pipe.");
        goto cleanup;
    }

    // Ensure NULL-termination
    buffer[bytesRead] = '\0';

    // Parse the buffer to extract working directory, command line options, and standard input
    sud->workingDir = _strdup(buffer);
    sud->commandLine = _strdup(buffer);
    sud->stdinData = _strdup(buffer);

    if (!sud->workingDir || !sud->commandLine || !sud->stdinData) {
        LogError("Failed to copy data into STARTUP_DATA structure.");
        goto cleanup;
    }

    result = TRUE;

cleanup:
    if (buffer && !result) {
        HeapFree(buffer);
    }

    return result;
}

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD bytesAvailable = 0;
    DWORD bytesRead = 0;
    BOOL result = FALSE;
    char* buffer = NULL;
    DWORD bufferLength = 0;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &bytesAvailable, NULL)) {
        LogError("Failed to peek into the named pipe.");
        return FALSE;
    }

    if (bytesAvailable == 0) {
        LogError("No data available in the named pipe.");
        return FALSE;
    }

    buffer = (char*)HeapAlloc(GENERIC_READ, bytesAvailable + 1);
    if (buffer == NULL) {
        LogError("Failed to allocate memory for reading data.");
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, bytesAvailable, &bytesRead, NULL)) {
        LogError("Failed to read data from the named pipe.");
        goto cleanup;
    }

    if (bytesRead != bytesAvailable) {
        LogError("Incomplete read from the named pipe.");
        goto cleanup;
    }

    buffer[bytesAvailable] = '\0';

    char* workingDirectory = strtok(buffer, "\n");
    char* commandLine = strtok(NULL, "\n");
    char* standardInput = strtok(NULL, "\n");

    if (!workingDirectory || !commandLine || !standardInput) {
        LogError("Invalid data format in the named pipe.");
        goto cleanup;
    }

    strncpy_s(sud->workingDirectory, MAX_PATH, workingDirectory, MAX_PATH);
    strncpy_s(sud->commandLine, MAX_CMD_LINE, commandLine, MAX_CMD_LINE);
    strncpy_s(sud->standardInput, MAX_STD_IN, standardInput, MAX_STD_IN);

    result = TRUE;

cleanup:
    if (buffer != NULL) {
        HeapFree(GENERIC_READ, buffer);
    }

    return result;
}

#include <windows.h>
#include <stdio.h>

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD dwRead = 0;
    DWORD dwAvail = 0;
    DWORD dwMsgAvail = 0;
    BOOL bResult = FALSE;
    DWORD dwPeekResult;
    char* buffer = NULL;
    char* workingDir = NULL;
    char* commandLine = NULL;
    char* stdinData = NULL;

    // Peek named pipe for available data
    dwPeekResult = PeekNamedPipe(pipe, NULL, 0, &dwRead, &dwAvail, &dwMsgAvail);
    if (!dwPeekResult || dwAvail == 0) {
        // Error or no data available
        fprintf(stderr, "PeekNamedPipe failed or no data available.\n");
        return FALSE;
    }

    // Allocate memory for data
    buffer = (char*)malloc(dwAvail + 1); // +1 for NULL termination
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed.\n");
        return FALSE;
    }

    // Read data from the pipe
    if (!ReadFile(pipe, buffer, dwAvail, &dwRead, NULL)) {
        fprintf(stderr, "ReadFile failed.\n");
        free(buffer);
        return FALSE;
    }

    // Ensure NULL termination
    buffer[dwAvail] = '\0';

    // Parse the data into the STARTUP_DATA structure
    sud->working_directory = _strdup(buffer);
    if (!sud->working_directory) {
        fprintf(stderr, "Failed to copy working directory.\n");
        free(buffer);
        return FALSE;
    }

    // Assume the command line starts after the working directory
    commandLine = strchr(buffer, '\0');
    if (commandLine) {
        commandLine++; // Move past the first NULL
        sud->command_line = _strdup(commandLine);
        if (!sud->command_line) {
            fprintf(stderr, "Failed to copy command line.\n");
            free(buffer);
            free(sud->working_directory);
            return FALSE;
        }

        // Assume stdin data starts after command line
        stdinData = strchr(commandLine, '\0');
        if (stdinData) {
            stdinData++; // Move past the NULL
            sud->stdin_data = _strdup(stdinData);
            if (!sud->stdin_data) {
                fprintf(stderr, "Failed to copy stdin data.\n");
                free(buffer);
                free(sud->working_directory);
                free(sud->command_line);
                return FALSE;
            }
        }
    }

    // Free the temporary buffer
    free(buffer);

    return TRUE;
}
